import type { PgDatabase, PgQueryResultHKT } from "drizzle-orm/pg-core";
import { drizzle, type BunSQLDatabase } from "drizzle-orm/bun-sql";
import { migrate } from "drizzle-orm/bun-sql/migrator";
import * as schema from "@/db/schema";

/**
 * Database handle used by the app's queries: any Postgres driver, so tests
 * can run the same queries on an in-memory Postgres (PGlite).
 */
export type Db = PgDatabase<PgQueryResultHKT, typeof schema>;

/** Folder with the SQL migrations generated by `bun run db:generate`. */
const MIGRATIONS_FOLDER = "drizzle";

/** Opens a connection pool to the Postgres at `url`. */
export function createDb(url: string): BunSQLDatabase<typeof schema> {
  return drizzle(url, { schema, casing: "snake_case" });
}

/**
 * Applies migrations from `drizzle/` that have not run yet; already applied
 * ones are tracked in the `drizzle.__drizzle_migrations` table.
 */
export async function runMigrations(
  db: BunSQLDatabase<typeof schema>,
): Promise<void> {
  await migrate(db, { migrationsFolder: MIGRATIONS_FOLDER });
}
